INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle Audioformate verlustfrei?', 2, '[{"text": "Nein", "correct": true, "because": "Es gibt verlustfreie und verlustbehaftete Formate"}, {"text": "Ja", "correct": false, "because": "Nicht alle sind verlustfrei"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Audioformat?', 3, '[{"text": "Audiodaten speichern", "correct": true, "because": "Primäre Funktion"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht Hauptzweck"}, {"text": "Bildqualität verbessern", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Audioformate gibt es?', 5, '[{"text": "MP3", "correct": true, "because": "Verlustbehaftet, weit verbreitet"}, {"text": "WAV", "correct": true, "because": "Verlustfrei, hohe Qualität"}, {"text": "JPEG", "correct": false, "because": "Bildformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FLAC ist ein verlustfreies Audioformat. b) MP3 hat immer die höchste Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MP3 ist verlustbehaftet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Audioformats?', 4, '[{"text": "Qualität", "correct": false, "because": "Entscheidend für Klang"}, {"text": "Dateigröße", "correct": false, "because": "Beeinflusst Speicher"}, {"text": "Farbtiefe", "correct": true, "because": "Bildfaktor, nicht Audio"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MP3 ein komprimiertes Format ist?', 2, '[{"text": "Ja", "correct": true, "because": "Verlustbehaftete Kompression"}, {"text": "Nein", "correct": false, "because": "Komprimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Audioformat ist verlustfrei?', 3, '[{"text": "FLAC", "correct": true, "because": "Keine Qualitätsverluste"}, {"text": "MP3", "correct": false, "because": "Verlustbehaftet"}, {"text": "AAC", "correct": false, "because": "Verlustbehaftet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu den Eigenschaften von WAV?', 5, '[{"text": "Verlustfreie Qualität", "correct": true, "because": "Keine Kompression"}, {"text": "Große Dateigröße", "correct": true, "because": "Unkomprimiert"}, {"text": "Hohe Kompression", "correct": false, "because": "Nicht komprimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) MP3 ist ein verlustbehaftetes Format. b) WAV unterstützt keine Metadaten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WAV kann Metadaten haben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Audioformaten unwichtig?', 4, '[{"text": "Bitrate", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Kompression", "correct": false, "because": "Entscheidet Größe"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Audiofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist AAC besser als MP3?', 2, '[{"text": "Ja", "correct": true, "because": "Bessere Qualität bei gleicher Bitrate"}, {"text": "Nein", "correct": false, "because": "Technisch überlegen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet FLAC?', 4, '[{"text": "Verlustfreie Qualität", "correct": true, "because": "Keine Datenverluste"}, {"text": "Kompression", "correct": true, "because": "Kleinere Dateien als WAV"}, {"text": "Maximale Geschwindigkeit", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass WAV immer die beste Qualität hat. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Verlustfrei, unkomprimiert"}, {"text": "Nein", "correct": false, "because": "Andere verlustfreie Formate gleichwertig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Audioformats?', 3, '[{"text": "Qualität", "correct": true, "because": "Entscheidend für Klang"}, {"text": "Kompatibilität", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MP3 reduziert die Dateigröße. b) FLAC ist größer als MP3.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "MP3 komprimiert, FLAC verlustfrei"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat MP3?', 5, '[{"text": "Qualitätsverlust", "correct": true, "because": "Verlustbehaftet"}, {"text": "Begrenzte Bitrate", "correct": true, "because": "Qualität eingeschränkt"}, {"text": "Kleine Dateigröße", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Audioformaten unwichtig?', 3, '[{"text": "Sample-Rate", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Kompressionstyp", "correct": false, "because": "Entscheidet Größe"}, {"text": "Textformatierung", "correct": true, "because": "Kein Audiofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt WAV hohe Bitraten?', 3, '[{"text": "Ja", "correct": true, "because": "Unkomprimiert, flexibel"}, {"text": "Nein", "correct": false, "because": "Keine Einschränkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob AAC eine Weiterentwicklung von MP3 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Effizientere Kompression"}, {"text": "Nein", "correct": false, "because": "Nachfolger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für maximale Qualität?', 4, '[{"text": "WAV", "correct": true, "because": "Verlustfrei, unkomprimiert"}, {"text": "MP3", "correct": false, "because": "Verlustbehaftet"}, {"text": "AAC", "correct": false, "because": "Verlustbehaftet"}]');
